-- METTLER TOLEDO (new brand): EasyPlus titrators (Easy pH, Easy Cl, Easy Ox, Easy Pro, Easy EPM, Easy Dose), EasyDirect titration software,
-- Densito / DensitoPro portable density meters and MyBrix refractometer (10 products). From the METTLER TOLEDO datasheets.
-- Photos: public/products/mettler-toledo/, logo: public/brands/mettler-toledo.png.
-- Run in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: products are updated by SKU.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('METTLER TOLEDO', 'mettler-toledo', 'https://www.mt.com/')
on conflict (slug) do update set name = excluded.name, website_url = coalesce(brands.website_url, excluded.website_url);
insert into categories (name, slug, sort_order) values ('Equipment', 'equipment', 5) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('MT-EASY-PH', 'METTLER TOLEDO EasyPlus™ Easy pH Titrator – Acid/Base', 'mettler-toledo-easyplus-easy-ph-titrator-acid-base-mt-easy-ph', 'The METTLER TOLEDO EasyPlus™ Easy pH is an affordable automated titrator for acid/base titrations to a pH endpoint or inflection point, plus simple pH measurement. Aqueous and non-aqueous pH sensors are available for any sample matrix. Standard delivery: EG11-BNC aqueous pH sensor, EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT with insert set, drying tube, valve, bottle head, burette cover set.', '[["Model", "EasyPlus™ Easy pH"], ["Type", "Automated acid/base titrator (pH endpoint and inflection/equivalence point) and pH measurement"], ["pH/mV input", "±2000 mV / 0 to 14 pH, resolution ±0.1 mV"], ["Temperature input", "0 to 100 °C, resolution ±0.1 °C"], ["Repeatability", "0.5 % RSD (depends on environment and handling)"], ["Titration types", "Direct, back compensated, blank compensated"], ["Display", "4.3 in. touchscreen, 480 × 272 pixel RGB"], ["Communication", "USB-A and USB-B (full / low speed)"], ["Power", "24 VDC / 1.25 A; line 100 to 240 V ±10 %, 50/60 Hz"], ["Environment", "5 to 40 °C, max. 80 % humidity at 31 °C"], ["Dimensions / weight", "170 × 220 × 350 mm (W × D × H) / 1.9 kg"], ["Standard delivery", "EG11-BNC aqueous pH sensor, EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT with insert set, drying tube, valve, bottle head, burette cover set"]]', '["Ideal for: acidity of juices, wines and milk", "Ideal for: alkalinity of cleaning reagents and chemicals", "Ideal for: free fatty acid content of cooking oils", "Ideal for: alkalinity (m-value) and acidity (p-value) of water", "Smartphone-style ''App'' interface: start routine analysis with a LongClick™ on the home screen", "15 languages for easy learning", "iTitrate™ Intelligence with EasySetup: set the minimum parameters and the titrator programs the rest, including calculations", "Swiss-engineered, very small footprint", "Print results on the USB-P25 printer or manage them with EasyDirect™ PC software"]', 'equipment', '/products/mettler-toledo/easy-ph.jpg'),
  ('MT-EASY-CL', 'METTLER TOLEDO EasyPlus™ Easy Cl Titrator – Chloride (Precipitation)', 'mettler-toledo-easyplus-easy-cl-titrator-chloride-precipitation-mt-easy-cl', 'The METTLER TOLEDO EasyPlus™ Easy Cl is an affordable automated titrator with a silver ring electrode for chloride determination by silver nitrate titration and other argentometric titrations. Standard delivery: EM45-BNC precipitation sensor (silver ring), EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT with insert set, drying tube, valve, bottle head, burette cover set.', '[["Model", "EasyPlus™ Easy Cl"], ["Type", "Automated precipitation (argentometric) titrator"], ["pH/mV input", "±2000 mV / 0 to 14 pH, resolution ±0.1 mV"], ["Repeatability", "0.5 % RSD (depends on environment and handling)"], ["Titration types", "Direct, back compensated, blank compensated"], ["Display", "4.3 in. touchscreen, 480 × 272 pixel RGB"], ["Communication", "USB-A and USB-B (full / low speed)"], ["Power", "24 VDC / 1.25 A; line 100 to 240 V ±10 %, 50/60 Hz"], ["Environment", "5 to 40 °C, max. 80 % humidity at 31 °C"], ["Dimensions / weight", "170 × 220 × 350 mm (W × D × H) / 1.9 kg"], ["Standard delivery", "EM45-BNC precipitation sensor (silver ring), EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT with insert set, drying tube, valve, bottle head, burette cover set"]]', '["Ideal for: chloride (salt) content of food and beverages", "Ideal for: salt content of waste or drinking water", "Ideal for: sulfide or mercaptan content of oils and lubricants", "Ideal for: silver content of solutions and dissolved metals", "Smartphone-style ''App'' interface: start routine analysis with a LongClick™ on the home screen", "15 languages for easy learning", "iTitrate™ Intelligence with EasySetup: set the minimum parameters and the titrator programs the rest, including calculations", "Swiss-engineered, very small footprint", "Print results on the USB-P25 printer or manage them with EasyDirect™ PC software"]', 'equipment', '/products/mettler-toledo/easy-cl.jpg'),
  ('MT-EASY-OX', 'METTLER TOLEDO EasyPlus™ Easy Ox Titrator – Redox', 'mettler-toledo-easyplus-easy-ox-titrator-redox-mt-easy-ox', 'The METTLER TOLEDO EasyPlus™ Easy Ox is an affordable automated titrator with a platinum ring electrode for inflection-point redox titrations in food, beverage, galvanic and environmental analysis. Standard delivery: EM40-BNC redox mV sensor (platinum ring), EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT with insert set, drying tube, valve, bottle head, burette cover set.', '[["Model", "EasyPlus™ Easy Ox"], ["Type", "Automated redox (oxidation/reduction) titrator"], ["mV input", "±2000 mV, resolution ±0.1 mV"], ["Polarized sensor input", "Ipol current source 0 to 5 µA (±0.1 µA); voltage input 0 to 2000 mV"], ["Repeatability", "0.5 % RSD (depends on environment and handling)"], ["Titration types", "Direct, back compensated, blank compensated"], ["Display", "4.3 in. touchscreen, 480 × 272 pixel RGB"], ["Communication", "USB-A and USB-B (full / low speed)"], ["Power", "24 VDC / 1.25 A; line 100 to 240 V ±10 %, 50/60 Hz"], ["Environment", "5 to 40 °C, max. 80 % humidity at 31 °C"], ["Dimensions / weight", "170 × 220 × 350 mm (W × D × H) / 1.9 kg"], ["Standard delivery", "EM40-BNC redox mV sensor (platinum ring), EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT with insert set, drying tube, valve, bottle head, burette cover set"]]', '["Ideal for: vitamin C in food and beverages", "Ideal for: peroxide value of cooking oils", "Ideal for: reducing sugar in wines and juices", "Ideal for: hydrogen peroxide in cleaning and plating solutions", "Smartphone-style ''App'' interface: start routine analysis with a LongClick™ on the home screen", "15 languages for easy learning", "iTitrate™ Intelligence with EasySetup: set the minimum parameters and the titrator programs the rest, including calculations", "Swiss-engineered, very small footprint", "Print results on the USB-P25 printer or manage them with EasyDirect™ PC software"]', 'equipment', '/products/mettler-toledo/easy-ox.jpg'),
  ('MT-EASY-PRO', 'METTLER TOLEDO EasyPlus™ Easy Pro Titrator – All-in-One', 'mettler-toledo-easyplus-easy-pro-titrator-all-in-one-mt-easy-pro', 'The METTLER TOLEDO EasyPlus™ Easy Pro is a versatile all-in-one titrator for acid/base inflection point, pH endpoint and precipitation/redox titrations. Optional sensors: EG13 non-aqueous pH, EM40 redox, EM43 Ipol and EM45 precipitation. Standard delivery: EG11-BNC aqueous pH sensor, EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT with insert set, drying tube, valve, bottle head, burette cover set.', '[["Model", "EasyPlus™ Easy Pro"], ["Type", "All-in-one titrator: acid/base, pH endpoint, precipitation and redox"], ["pH/mV input", "±2000 mV / 0 to 14 pH, resolution ±0.1 mV"], ["Polarized sensor input", "Ipol current source 0 to 5 µA (±0.1 µA); voltage input 0 to 2000 mV"], ["Temperature input", "0 to 100 °C, resolution ±0.1 °C"], ["Repeatability", "0.5 % RSD (depends on environment and handling)"], ["Titration types", "Direct, back compensated, blank compensated"], ["Display", "4.3 in. touchscreen, 480 × 272 pixel RGB"], ["Communication", "USB-A and USB-B (full / low speed)"], ["Power", "24 VDC / 1.25 A; line 100 to 240 V ±10 %, 50/60 Hz"], ["Environment", "5 to 40 °C, max. 80 % humidity at 31 °C"], ["Dimensions / weight", "170 × 220 × 350 mm (W × D × H) / 1.9 kg"], ["Standard delivery", "EG11-BNC aqueous pH sensor, EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT with insert set, drying tube, valve, bottle head, burette cover set"]]', '["Ideal for: pH endpoint titrations in juice and wine, p- and m-value", "Ideal for: acid/base equivalence point titrations (free fatty acids, alkalinity)", "Ideal for: precipitation titrations such as chloride in food or water", "Ideal for: redox titrations such as vitamin C, reducing sugar and sulfite", "Smartphone-style ''App'' interface: start routine analysis with a LongClick™ on the home screen", "15 languages for easy learning", "iTitrate™ Intelligence with EasySetup: set the minimum parameters and the titrator programs the rest, including calculations", "Swiss-engineered, very small footprint", "Print results on the USB-P25 printer or manage them with EasyDirect™ PC software"]', 'equipment', '/products/mettler-toledo/easy-pro.jpg'),
  ('MT-EASY-EPM', 'METTLER TOLEDO EasyPlus™ Easy EPM Semi-Automated Titrator', 'mettler-toledo-easyplus-easy-epm-semi-automated-titrator-mt-easy-epm', 'The METTLER TOLEDO Easy EPM simplifies and speeds up manual titration, standard preparation and dispensing. The automated burette with immersed dispensing tip avoids drop-to-drop variation, and an optional pH sensor guides you through manual titrations to avoid over-titration. Standard delivery: EasyPlus burette 20 mL, tubing set, EasyStir GT, titration head GT, drying tube, valve, bottle head, burette cover set.', '[["Model", "Easy EPM"], ["Type", "Semi-automated titration, standard preparation and dispensing"], ["Optional sensors", "EG11-BNC aqueous pH (30043103), EG13-BNC non-aqueous pH (30043104), temperature sensor 30K (51300164)"], ["Display", "4.3 in. touchscreen, 480 × 272 pixel RGB"], ["Communication", "USB-A and USB-B (full / low speed)"], ["Power", "24 VDC / 1.25 A; line 100 to 240 V ±10 %, 50/60 Hz"], ["Environment", "5 to 40 °C, max. 80 % humidity at 31 °C"], ["Dimensions / weight", "170 × 220 × 350 mm (W × D × H) / 1.9 kg"], ["Standard delivery", "EasyPlus burette 20 mL (30043901), tubing set (30065464), EasyStir GT (30065467), titration head GT (30041102), drying tube (30044701), valve (30042860), bottle head (30060023), burette cover set (30057633)"], ["Accessories", "EasyWheel USB controller (30459699), USB-P25 strip printer (11124301), burettes 10 / 50 mL"]]', '["Precise semi-automated titrations with an immersed dispensing tip", "Optional pH sensor guides manual titrations and minimises over-titration", "Operate by 4.3 in. touchscreen or the optional USB EasyWheel controller", "iTitrate™ Intelligence with EasySetup for simple method programming", "Export results to USB flash drive or print directly", "Ideal for acid content of juices/wines/milk, alkalinity, free fatty acids and water p/m-values"]', 'equipment', '/products/mettler-toledo/easy-epm.jpg'),
  ('MT-EASY-DOSE', 'METTLER TOLEDO EasyPlus™ Easy Dose Dispenser', 'mettler-toledo-easyplus-easy-dose-dispenser-mt-easy-dose', 'The METTLER TOLEDO Easy Dose simplifies and speeds up standard preparation and dispensing. Dispense by volume, speed or time; enter the sample weight and target concentration and it prepares your standards automatically. Connect an MS, ML or ME balance for automatic weight transfer. Standard delivery: EasyPlus burette 50 mL, tubing set, drying tube, valve, bottle head, burette cover set.', '[["Model", "Easy Dose"], ["Type", "Automatic standard preparation and dispensing"], ["Dispensing modes", "By volume, speed or time"], ["Balance connection", "METTLER TOLEDO MS, ML or ME balance for automatic weight transfer"], ["Display", "4.3 in. touchscreen, 480 × 272 pixel RGB"], ["Communication", "USB-A and USB-B (full / low speed)"], ["Power", "24 VDC / 1.25 A; line 100 to 240 V ±10 %, 50/60 Hz"], ["Environment", "5 to 40 °C, max. 80 % humidity at 31 °C"], ["Dimensions / weight", "170 × 220 × 350 mm (W × D × H) / 1.9 kg"], ["Standard delivery", "EasyPlus burette 50 mL (30043902), tubing set (30065464), drying tube (30044701), valve (30042860), bottle head (30060023), burette cover set (30057633)"], ["Accessories", "Burettes 10 / 20 mL, EasyStir GT, titration head GT, EasyWheel (30459699), USB-P25 strip printer (11124301)"]]', '["Prepares standards automatically from sample weight and target concentration", "Automatic weight transfer from a connected balance avoids transcription errors", "Start tasks with one tap; 15 languages", "Touchscreen or optional USB EasyWheel controller", "Export to USB flash drive or print directly"]', 'equipment', '/products/mettler-toledo/easy-dose.jpg'),
  ('MT-EASYDIRECT-TITRATION', 'METTLER TOLEDO EasyDirect™ Titration PC Software (license for 3 titrators)', 'mettler-toledo-easydirect-titration-pc-software-license-for-3-titrators-mt-easydirect-titration', 'EasyDirect™ Titration Software collects results and measured values from up to three EasyPlus™ titrators on one PC, even when the software is not running. Review titration curves, export to CSV, print on a local or network printer and add an extra calculation for each instrument. Order number 30065449; a 45-day free trial is available from METTLER TOLEDO.', '[["Order number", "30065449 (instrument license for 3 titrators per PC)"], ["Compatible with", "EasyPlus™ titrators (Easy pH, Easy Cl, Easy Ox, Easy Pro, Easy EPM)"], ["Functions", "Result capture and storage by method type, curve viewer with 1st derivative, CSV export, local/network printing, additional calculation with statistics"]]', '["Collects results from up to three EasyPlus™ titrators automatically", "Graph viewer with 1st derivative for equivalence point titrations", "Export single samples or all results to CSV", "Print exactly what you need on local or network printers", "Extra calculation and statistics per instrument"]', 'equipment', '/products/mettler-toledo/easydirect.jpg'),
  ('MT-30330857', 'METTLER TOLEDO Densito Portable Density Meter', 'mettler-toledo-densito-portable-density-meter-mt-30330857', 'The METTLER TOLEDO Densito is a light, rugged handheld density meter for the lab and on the go: from incoming goods inspection to at-line quality control. Measures density, Brix, alcohol and many other scales with automatic temperature compensation. Material number 30330857.', '[["Material number", "30330857"], ["Ambient temperature", "-10 to 50 °C"], ["Density range", "0.000 to 3.000 g/cm³"], ["Density accuracy / repeatability", "±0.001 / ±0.0005 g/cm³"], ["Density resolution", "0.0001 g/cm³"], ["Sample temperature", "0 to 50 °C (resolution 0.1 °C, accuracy ±0.2 °C)"], ["Measurement scales", "Density, specific gravity, ethanol (alcohol), Brix, API, Baumé, H2SO4, Plato, proof (US and IP), user-defined concentration"], ["Temperature compensation", "Automatic or user-defined coefficient"], ["Sample volume", "2 mL"], ["Methods / results", "Up to 30 methods; 1100 results stored"], ["Display", "2.4 in. colour screen; buttons and joystick"], ["Connectivity", "USB-A (USB-P25 or Bluetooth printer), USB-C (EasyDirect PC software)"], ["Security", "Password protection"], ["Battery", "Rechargeable, removable lithium-ion"], ["Weight", "355 g"]]', '["Measure density anywhere: dip the tube in the sample and get a result in seconds", "Built-in pump fills and empties the cell at the press of a button", "Bright colour display readable indoors and outdoors", "Limits flag out-of-spec results; guided procedures from measurement to cleaning", "Stores 1100 results; EasyDirect software for review, graphs and reports"]', 'equipment', '/products/mettler-toledo/densito.jpg'),
  ('MT-30330858', 'METTLER TOLEDO DensitoPro Portable Density Meter with RFID and Barcode Reader', 'mettler-toledo-densitopro-portable-density-meter-with-rfid-and-barcode-reader-mt-30330858', 'The METTLER TOLEDO DensitoPro is the handheld density meter with a built-in RFID and barcode reader for point-and-shoot sample ID entry. Measures density, Brix, alcohol and many other scales with automatic temperature compensation. Material number 30330858.', '[["Material number", "30330858"], ["Ambient temperature", "0 to 50 °C"], ["Sample ID", "RFID and barcode reader"], ["Density range", "0.000 to 3.000 g/cm³"], ["Density accuracy / repeatability", "±0.001 / ±0.0005 g/cm³"], ["Density resolution", "0.0001 g/cm³"], ["Sample temperature", "0 to 50 °C (resolution 0.1 °C, accuracy ±0.2 °C)"], ["Measurement scales", "Density, specific gravity, ethanol (alcohol), Brix, API, Baumé, H2SO4, Plato, proof (US and IP), user-defined concentration"], ["Temperature compensation", "Automatic or user-defined coefficient"], ["Sample volume", "2 mL"], ["Methods / results", "Up to 30 methods; 1100 results stored"], ["Display", "2.4 in. colour screen; buttons and joystick"], ["Connectivity", "USB-A (USB-P25 or Bluetooth printer), USB-C (EasyDirect PC software)"], ["Security", "Password protection"], ["Battery", "Rechargeable, removable lithium-ion"], ["Weight", "355 g"]]', '["RFID and barcode reader for simple point-and-shoot sample ID", "Measure density anywhere: dip the tube in the sample and get a result in seconds", "Built-in pump fills and empties the cell at the press of a button", "Bright colour display readable indoors and outdoors", "Limits flag out-of-spec results; guided procedures from measurement to cleaning", "Stores 1100 results; EasyDirect software for review, graphs and reports"]', 'equipment', '/products/mettler-toledo/densitopro.jpg'),
  ('MT-30693200', 'METTLER TOLEDO MyBrix Handheld Digital Refractometer', 'mettler-toledo-mybrix-handheld-digital-refractometer-mt-30693200', 'The METTLER TOLEDO MyBrix measures refractive index and sugar content in 2 seconds across the full 0 to 95 °Brix range. Compact, robust and weatherproof (IP65), it is ideal for harvest timing, incoming goods inspection and quality control in juice, wine, soft drink and food production. Material number 30693200.', '[["Material number", "30693200 (pack of 10: 30693201)"], ["Brix range / accuracy / resolution", "0 to 95 % w/w / ±0.2 / 0.1"], ["Refractive index range / accuracy / resolution", "1.33 to 1.53 nD / ±0.0003 / 0.0001"], ["Scales", "Refractive index, Brix, Brix ATC 20 °C, HFCS 42 / 55 / 90, Baumé, KMW (Babo), Oechsle German / Swiss, Plato, wort"], ["Measurement time", "2 seconds"], ["Sample volume", "0.3 mL"], ["Display", "1.8 in. digital LCD"], ["Wetted parts", "8 mm optical glass, stainless steel; ABS case"], ["Protection", "IP65; < 95 % RH non-condensing"], ["Power", "2 × AAA (3 V), about 10,000 readings"], ["Dimensions / weight", "115 × 54 × 30 mm / 115 g with batteries"], ["Special features", "High ambient light detection, error messages, battery indicator"]]', '["Results in 2 seconds with automatic temperature compensation", "Full Brix range 0 to 95 % for almost any food and beverage sample", "Shows up to 3 of 10 sugar-related scales at once", "Compact, robust and weatherproof (IP65) for field, line or lab", "Replaces analog refractometers: no operator dependency"]', 'equipment', '/products/mettler-toledo/mybrix.jpg')
) as v(sku, name, slug, description, specs, features, cat, image_url)
join categories c on c.slug = v.cat
cross join (select id from brands where slug = 'mettler-toledo') b
on conflict (sku) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id, image_url = excluded.image_url, is_active = true;

select count(*) as products from products p join brands b on b.id = p.brand_id where b.slug = 'mettler-toledo' and p.is_active;
